{
  "claims": [
    {
      "citations": [
        "S1"
      ],
      "text": "El Consejo Europeo de Inteligencia Artificial debe apoyar a la Comisión para promover las herramientas de alfabetización en materia de IA, la sensibilización pública y la comprensión de los beneficios."
    },
    {
      "citations": [
        "S2"
      ],
      "text": "La Comisión y los Estados miembros deben facilitar la elaboración de códigos de conducta voluntarios para promover la alfabetización en materia de IA entre las personas que se ocupan del desarrollo, el manejo y el uso de la IA."
    },
    {
      "citations": [
        "S5"
      ],
      "text": "Los proveedores y responsables del despliegue de sistemas de IA adoptarán medidas para garantizar que su personal y demás personas que se encarguen en su nombre del funcionamiento y la utilización de sistemas de IA tengan un nivel suficiente de alfabetización en materia de IA."
    },
    {
      "citations": [
        "S6"
      ],
      "text": "La alfabetización en materia de IA debe dotar a los proveedores, responsables del despliegue y personas afectadas de los conceptos necesarios para tomar decisiones con conocimiento de causa en relación con los sistemas de IA."
    }
  ],
  "status": "answered"
}

